code_bool Amalgame_Compiler_Base64_IsValid(code_string s) {
    i64 n = String_Length(s);
    if (n == 0) {
        return 1;
    }
    code_string alpha = Amalgame_Compiler_Base64_Alphabet();
    i64 pos = 0;
    code_bool sawEqual = 0;
    for (i64 i = 0; i < n; i++) {
        code_string c = String_CharAt1(s, i);
        if (code_string_equals(c, "=")) {
            sawEqual = 1;
        } else {
            if (sawEqual) {
                return 0;
            }
            i64 v = String_IndexOf(alpha, c);
            if (v < 0) {
                return 0;
            }
        }
        pos = pos + 1;
    }
    return 1;
}

static code_string Amalgame_Compiler_Base64_EncodeWith(AmalgameList* bytes, code_string alpha, code_bool pad) {
    i64 n = AmalgameList_count(bytes);
    if (n == 0) {
        return "";
    }
    code_string out = "";
    i64 i = 0;
    while (i + 3 <= n) {
        i64 b0 = (i64)AmalgameList_get(bytes, i) & 255;
        i64 b1 = (i64)AmalgameList_get(bytes, i + 1) & 255;
        i64 b2 = (i64)AmalgameList_get(bytes, i + 2) & 255;
        i64 v0 = b0 / 4;
        i64 lo0 = b0 & 3;
        i64 v1 = lo0 * 16 + b1 / 16;
        i64 lo1 = b1 & 15;
        i64 v2 = lo1 * 4 + b2 / 64;
        i64 v3 = b2 & 63;
        out = code_string_concat(out, String_CharAt1(alpha, v0));
        out = code_string_concat(out, String_CharAt1(alpha, v1));
        out = code_string_concat(out, String_CharAt1(alpha, v2));
        out = code_string_concat(out, String_CharAt1(alpha, v3));
        i = i + 3;
    }
    i64 remaining = n - i;
    if (remaining == 1) {
        i64 b0 = (i64)AmalgameList_get(bytes, i) & 255;
        i64 v0 = b0 / 4;
        i64 lo0 = b0 & 3;
        i64 v1 = lo0 * 16;
        out = code_string_concat(out, String_CharAt1(alpha, v0));
        out = code_string_concat(out, String_CharAt1(alpha, v1));
        if (pad) {
            out = code_string_concat(out, "==");
        }
    }
    if (remaining == 2) {
        i64 b0 = (i64)AmalgameList_get(bytes, i) & 255;
        i64 b1 = (i64)AmalgameList_get(bytes, i + 1) & 255;
        i64 v0 = b0 / 4;
        i64 lo0 = b0 & 3;
        i64 v1 = lo0 * 16 + b1 / 16;
        i64 lo1 = b1 & 15;
        i64 v2 = lo1 * 4;
        out = code_string_concat(out, String_CharAt1(alpha, v0));
        out = code_string_concat(out, String_CharAt1(alpha, v1));
        out = code_string_concat(out, String_CharAt1(alpha, v2));
        if (pad) {
            out = code_string_concat(out, "=");
        }
    }
    return out;
}

static AmalgameList* Amalgame_Compiler_Base64_DecodeWith(code_string s, code_string alpha) {
    AmalgameList* out = AmalgameList_new();
    i64 n = String_Length(s);
    if (n == 0) {
        return out;
    }
    i64 end = n;
    code_bool stripping = 1;
    while (stripping && end > 0) {
        i64 lastIdx = end - 1;
        code_string last = String_CharAt1(s, lastIdx);
        if (code_string_equals(last, "=")) {
            end = end - 1;
        } else {
            stripping = 0;
        }
    }
    i64 i = 0;
    while (i + 4 <= end) {
        code_string c0 = String_CharAt1(s, i);
        code_string c1 = String_CharAt1(s, i + 1);
        code_string c2 = String_CharAt1(s, i + 2);
        code_string c3 = String_CharAt1(s, i + 3);
        i64 v0 = String_IndexOf(alpha, c0);
        i64 v1 = String_IndexOf(alpha, c1);
        i64 v2 = String_IndexOf(alpha, c2);
        i64 v3 = String_IndexOf(alpha, c3);
        if (v0 < 0 || v1 < 0 || v2 < 0 || v3 < 0) {
            return AmalgameList_new();
        }
        i64 b0 = v0 * 4 + v1 / 16;
        i64 lo1 = v1 & 15;
        i64 b1 = lo1 * 16 + v2 / 4;
        i64 lo2 = v2 & 3;
        i64 b2 = lo2 * 64 + v3;
        AmalgameList_add(out, (void*)(intptr_t)(b0 & 255));
        AmalgameList_add(out, (void*)(intptr_t)(b1 & 255));
        AmalgameList_add(out, (void*)(intptr_t)(b2 & 255));
        i = i + 4;
    }
    i64 leftover = end - i;
    if (leftover == 2) {
        code_string c0 = String_CharAt1(s, i);
        code_string c1 = String_CharAt1(s, i + 1);
        i64 v0 = String_IndexOf(alpha, c0);
        i64 v1 = String_IndexOf(alpha, c1);
        if (v0 < 0 || v1 < 0) {
            return AmalgameList_new();
        }
        i64 b0 = v0 * 4 + v1 / 16;
        AmalgameList_add(out, (void*)(intptr_t)(b0 & 255));
    }
    if (leftover == 3) {
        code_string c0 = String_CharAt1(s, i);
        code_string c1 = String_CharAt1(s, i + 1);
        code_string c2 = String_CharAt1(s, i + 2);
        i64 v0 = String_IndexOf(alpha, c0);
        i64 v1 = String_IndexOf(alpha, c1);
        i64 v2 = String_IndexOf(alpha, c2);
        if (v0 < 0 || v1 < 0 || v2 < 0) {
            return AmalgameList_new();
        }
        i64 b0 = v0 * 4 + v1 / 16;
        i64 lo1 = v1 & 15;
        i64 b1 = lo1 * 16 + v2 / 4;
        AmalgameList_add(out, (void*)(intptr_t)(b0 & 255));
        AmalgameList_add(out, (void*)(intptr_t)(b1 & 255));
    }
    return out;
}

