AmalgameList* Amalgame_Compiler_Hex_Decode(code_string s) {
    AmalgameList* out = AmalgameList_new();
    i64 n = String_Length(s);
    if (n == 0) {
        return out;
    }
    i64 half = n / 2;
    i64 half2 = half * 2;
    if (half2 != n) {
        return AmalgameList_new();
    }
    i64 i = 0;
    while (i < n) {
        code_string c0 = String_CharAt1(s, i);
        code_string c1 = String_CharAt1(s, i + 1);
        i64 v0 = Amalgame_Compiler_Hex_HexValue(c0);
        i64 v1 = Amalgame_Compiler_Hex_HexValue(c1);
        if (v0 < 0 || v1 < 0) {
            return AmalgameList_new();
        }
        i64 b = v0 * 16 + v1;
        AmalgameList_add(out, (void*)(intptr_t)(b));
        i = i + 2;
    }
    return out;
}

code_bool Amalgame_Compiler_Hex_IsValid(code_string s) {
    i64 n = String_Length(s);
    i64 half = n / 2;
    i64 half2 = half * 2;
    if (half2 != n) {
        return 0;
    }
    for (i64 i = 0; i < n; i++) {
        code_string c = String_CharAt1(s, i);
        i64 v = Amalgame_Compiler_Hex_HexValue(c);
        if (v < 0) {
            return 0;
        }
    }
    return 1;
}

static code_string Amalgame_Compiler_Hex_EncodeWith(AmalgameList* bytes, code_string alpha) {
    i64 n = AmalgameList_count(bytes);
    code_string out = "";
    for (i64 i = 0; i < n; i++) {
        i64 b = (i64)AmalgameList_get(bytes, i) & 255;
        i64 hi = b / 16;
        i64 lo = b & 15;
        out = code_string_concat(out, String_CharAt1(alpha, hi));
        out = code_string_concat(out, String_CharAt1(alpha, lo));
    }
    return out;
}

static i64 Amalgame_Compiler_Hex_HexValue(code_string c) {
    i64 lower = String_IndexOf("0123456789abcdef", c);
    if (lower >= 0) {
        return lower;
    }
    i64 upper = String_IndexOf("0123456789ABCDEF", c);
    if (upper >= 0) {
        return upper;
    }
    return -1;
}

