    AmalgameList_add(out, (void*)(intptr_t)(Amalgame_Compiler_MsgPack_ByteOf(v, 2)));
    AmalgameList_add(out, (void*)(intptr_t)(Amalgame_Compiler_MsgPack_ByteOf(v, 1)));
